import data from "@/data/nationalSchools.json";
import type { School } from "@/data/schools";

/**
 * Page-capable national schools (PAGE_ONLY) — every CONFIRMED NEIS school with exactly one official 행정동 and a
 * city node in src/data/regions.ts that is not registered in src/data/schools.ts. Generated by
 * scripts/official/national-school-pages.ts from data/official/school-candidates.json; do not edit by hand.
 *
 * Policy (docs/qa/national-school-expansion-readiness-2026-11-02.md):
 * - /school/[slug] renders a fact-only hub for these (name, 학교급, 소재 지역, 행정동, source) — always
 *   noindex, follow and never in the sitemap. No school×subject route exists for them (404).
 * - They are deliberately kept OUT of `schools`: registered schools drive the region / combo / dong gates
 *   (countSchoolsInRegion, hasRegionComboRoutes), and 10k unreviewed rows must not switch those on.
 * - PENDING / EXCLUDED / unmapped-region (광주·전남·세종) schools are not in the file → 404.
 */
export interface NationalSchool {
  code: string;
  slug: string;
  name: string;
  level: School["level"];
  /** NEIS 시도교육청 코드. */
  office: string;
  cityRegionSlug: string;
  districtRegionSlug?: string;
  /** 행정안전부 행정동코드 / 행정동명 (data/official/national-school-dongs.json, 2026-10-12 코드). */
  dongCode: string;
  dongName: string;
}

const rows = data.rows as string[][];

let bySlug: Map<string, NationalSchool> | undefined;

function toSchool(r: string[]): NationalSchool {
  const [code, slug, name, level, office, citySlug, districtSlug, dongCode, dongName] = r;
  return {
    code,
    slug,
    name,
    level: level as School["level"],
    office,
    cityRegionSlug: citySlug,
    ...(districtSlug ? { districtRegionSlug: districtSlug } : {}),
    dongCode,
    dongName,
  };
}

export function getNationalSchoolBySlug(slug: string): NationalSchool | undefined {
  bySlug ??= new Map(rows.map((r) => [r[1], toSchool(r)]));
  return bySlug.get(slug);
}

export function allNationalSchools(): NationalSchool[] {
  return rows.map(toSchool);
}

/** Per-school data basis shown on the page (same NEIS endpoint as src/data/sources.ts neisSchoolSource). */
export function nationalSchoolSource(s: NationalSchool): { label: string; url: string } {
  return {
    label: `교육부 NEIS 학교기본정보 — ${s.name}`,
    url: `https://open.neis.go.kr/hub/schoolInfo?Type=json&ATPT_OFCDC_SC_CODE=${s.office}&SD_SCHUL_CODE=${s.code}`,
  };
}
